/* ══════════════════════════════════════
   STATE
══════════════════════════════════════ */
const FORMATS = {
  a: { strips:2, photos:3, label:'Format A — 2 portrait strips · 3 photos each · B5 (182×257mm) scale 100'},
  b: { strips:2, photos:4, label:'Format B — 6×4 4-Pose · 2 strips · B6 (128×182mm) scale 98' },
  c: { strips:1, photos:3, label:'Format C — 1 portrait strip · 3 photos · B6 (128x182mm) scale 77' },
  d: { strips:1, photos:4, label:'Format D — 6×4 4-Pose · 1 strip · B6 (128×182mm)' }
};

let currentFormat = 'a';
let currentTheme  = 'default';
const photoData   = {};

/* ══════════════════════════════════════
   SVG HELPERS
══════════════════════════════════════ */
function camSvg() {
  return `<svg class="slot-icon" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="1.5">
    <rect x="2" y="5" width="20" height="15" rx="3"/>
    <circle cx="12" cy="12.5" r="3.5"/>
    <path d="M7 5V4a1 1 0 011-1h8a1 1 0 011 1v1"/>
  </svg>`;
}

function airplaySvg() {
  return `<svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,0.5)" stroke-width="2">
    <path d="M5 17H3a2 2 0 01-2-2V5a2 2 0 012-2h18a2 2 0 012 2v10a2 2 0 01-2 2h-2"/>
    <polygon points="12 15 17 21 7 21 12 15"/>
  </svg>`;
}

/* ══════════════════════════════════════
   STRIP BUILDERS
══════════════════════════════════════ */
function buildPhotoSlots(si, count) {
  let html = '';
  for (let p = 0; p < count; p++) {
    const key    = `${si}_${p}`;
    const hasCls = photoData[key] ? 'has-photo' : '';
    html += `<div class="photo-slot ${hasCls}" id="slot_${si}_${p}" onclick="triggerUpload(${si},${p})">
      <img id="img_${si}_${p}" src="${photoData[key] || ''}" alt="">
      <div class="slot-label">${camSvg()}<span class="slot-num">PHOTO ${p + 1}</span></div>
    </div>`;
  }
  return html;
}

function buildPlayerHTML() {
  return `<div class="player">
    <div class="player-device">CHMSU U-WEEK 2026</div>
    <div class="player-top">
      <div class="player-info">
        <input class="player-title-inp" type="text" value="seasons" maxlength="38">
        <input class="player-sub-inp"   type="text" value="wave to earth" maxlength="30">
      </div>
      <div class="player-icon">${airplaySvg()}</div>
    </div>
    <div class="progress-row">
      <span class="ptime">0:50</span>
      <div class="pbar"><div class="pfill"></div></div>
      <span class="ptime right">−3:26</span>
    </div>
    <div class="controls">
      <button class="ctrl-btn">
        <svg width="11" height="11" viewBox="0 0 24 24" fill="rgba(255,255,255,0.75)"><path d="M6 6h2v12H6zm3.5 6 8.5 6V6z"/></svg>
      </button>
      <button class="ctrl-btn play">
        <svg width="8" height="8" viewBox="0 0 24 24" fill="rgba(255,255,255,0.9)"><rect x="6" y="4" width="4" height="16" rx="1"/><rect x="14" y="4" width="4" height="16" rx="1"/></svg>
      </button>
      <button class="ctrl-btn">
        <svg width="11" height="11" viewBox="0 0 24 24" fill="rgba(255,255,255,0.75)"><path d="M6 18l8.5-6L6 6v12zm2-12v12h2V6h-2z"/><rect x="16" y="6" width="2" height="12" rx="1"/></svg>
      </button>
    </div>
  </div>`;
}

/* Camera header HTML — only visible in polaroid theme via CSS */
function buildCameraHeader() {
  return `<div class="cam-header">
    <div class="cam-body">
      <div class="cam-left">
        <div class="cam-flash"></div>
        <div class="cam-viewfinder"></div>
      </div>
      <div class="cam-lens-wrap">
        <div class="cam-lens">
          <div class="cam-lens-inner"></div>
          <div class="cam-lens-dot"></div>
        </div>
      </div>
      <div class="cam-right">
        <div class="cam-shutter"></div>
      </div>
    </div>
    <div class="cam-stripe"></div>
  </div>`;
}

/* Format A / C strip (3 photos + music player) */
function buildStripA(si) {
  const inner = `<div class="strip" id="strip_${si}">
    ${buildCameraHeader()}
    <div class="photos">${buildPhotoSlots(si, 3)}</div>
    ${buildPlayerHTML()}
    <div class="watermark-wrap">
      <div class="watermark-logos">
        <img class="wm-logo-img" src="data:image/png;base64," alt="CHMSU">
        <img class="wm-logo-img" src="data:image/png;base64," alt="ITS">
      </div>
      <input class="watermark-inp" type="text" value="PIXL">
    </div>
  </div>`;
  return `<div class="film-wrap">${inner}</div>`;
}

/* Format B strip (4 photos in 2×2 grid + event footer) */
function buildStripB(si) {
  const inner = `<div class="strip" id="strip_${si}">
    ${buildCameraHeader()}
    <div class="photos">${buildPhotoSlots(si, 4)}</div>
    <div class="strip-footer">
      <div class="footer-logos">
        <img class="footer-logo-img" src="data:image/png;base64," alt="CHMSU">
        <img class="footer-logo-img" src="data:image/png;base64," alt="ITS">
      </div>
      <div class="footer-left">
        <input class="footer-event" type="text" value="CHMSU U-WEEK 2026" maxlength="30">
        <input class="footer-sub"   type="text" value="Information Technology Society" maxlength="36">
      </div>
      <div class="footer-right">
        <input class="footer-brand" type="text" value="PIXL" maxlength="24">
      </div>
    </div>
  </div>`
;
  return `<div class="film-wrap">${inner}</div>`;
}

/* ══════════════════════════════════════
   RENDER
══════════════════════════════════════ */
function render() {
  const f = FORMATS[currentFormat];
  let html = '';
  for (let i = 0; i < f.strips; i++) {
    html += (currentFormat === 'b' || currentFormat === 'd') ? buildStripB(i) : buildStripA(i);
  }
  document.getElementById('page').innerHTML = html;
  document.getElementById('fmt-label').textContent = f.label;
}

/* ══════════════════════════════════════
   FORMAT SWITCHER
══════════════════════════════════════ */
function setFormat(fmt) {
  currentFormat = fmt;
  applyBodyClass();
  document.querySelectorAll('.fmt-btn').forEach((b, i) => {
    b.classList.toggle('active', ['a', 'b', 'c', 'd'][i] === fmt);
  });
  render();
}

/* ══════════════════════════════════════
   THEME SWITCHER
══════════════════════════════════════ */
function setTheme(theme) {
  currentTheme = theme;
  applyBodyClass();
  document.querySelectorAll('.theme-btn').forEach(b => {
    b.classList.toggle('active', b.getAttribute('onclick') === `setTheme('${theme}')`);
  });
}

function applyBodyClass() {
  const themeClass = currentTheme === 'default' ? '' : `theme-${currentTheme}`;
  document.body.className = `fmt-${currentFormat} ${themeClass}`.trim();
}

/* ══════════════════════════════════════
   PHOTO UPLOAD
══════════════════════════════════════ */
function triggerUpload(si, pi) {
  const id = `file_${si}_${pi}`;
  let inp = document.getElementById(id);
  if (!inp) {
    inp = document.createElement('input');
    inp.type = 'file';
    inp.accept = 'image/*';
    inp.id = id;
    inp.style.display = 'none';
    inp.onchange = () => loadImage(si, pi, inp);
    document.getElementById('file-inputs').appendChild(inp);
  }
  inp.click();
}

function loadImage(si, pi, inp) {
  const file = inp.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = e => {
    const dataURL = e.target.result;
    const totalStrips = FORMATS[currentFormat].strips;

    // Mirror the same photo slot across ALL strips
    for (let s = 0; s < totalStrips; s++) {
      photoData[`${s}_${pi}`] = dataURL;
      const img  = document.getElementById(`img_${s}_${pi}`);
      const slot = document.getElementById(`slot_${s}_${pi}`);
      if (img)  img.src = dataURL;
      if (slot) slot.classList.add('has-photo');
    }
  };
  reader.readAsDataURL(file);
}

/* ══════════════════════════════════════
   CLEAR
══════════════════════════════════════ */
function clearAll() {
  Object.keys(photoData).forEach(k => delete photoData[k]);
  document.getElementById('file-inputs').innerHTML = '';
  render();
}

/* ══════════════════════════════════════
   SAVE AS PDF
══════════════════════════════════════ */
async function savePDF() {
  const { jsPDF } = window.jspdf;
  const page = document.getElementById('page');

  const sizes = {
    a: { w: 128, h: 182 },
    b: { w: 128, h: 182 },
    c: { w: 128, h: 182 }
  };
  const { w, h } = sizes[currentFormat];

  const btn = document.querySelector('.action-btn.primary');
  btn.textContent = '⏳ Generating…';
  btn.disabled = true;

  // Save original styles
  const prevStyles = {
    width:     page.style.width,
    height:    page.style.height,
    overflow:  page.style.overflow,
    position:  page.style.position,
    transform: page.style.transform,
    zoom:      page.style.zoom
  };

  // 3.7795 px per mm at 96dpi
  const PX_PER_MM = 3.7795;
  const pxW = Math.round(w * PX_PER_MM);
  const pxH = Math.round(h * PX_PER_MM);

  // Force page to exact print size, no zoom
  page.style.width    = pxW + 'px';
  page.style.height   = pxH + 'px';
  page.style.overflow = 'visible';
  page.style.zoom     = '1';
  page.style.transform = 'none';

  // Wait for layout + fonts to settle
  await new Promise(r => setTimeout(r, 400));

  try {
    const canvas = await html2canvas(page, {
      scale: 4,
      useCORS: true,
      allowTaint: true,
      backgroundColor: '#ffffff',
      width:  pxW,
      height: pxH,
      scrollX: 0,
      scrollY: 0,
      logging: false,
      letterRendering: true,
      onclone: (doc) => {
        // Replace each input with a styled span so html2canvas renders text+fonts correctly
        doc.querySelectorAll('input[type="text"]').forEach(inp => {
          const computed = window.getComputedStyle(inp);
          const span = doc.createElement('span');
          span.textContent = inp.value;
          // Copy only the properties that matter for text rendering
          const props = [
            'font-family','font-size','font-weight','font-style',
            'color','letter-spacing','line-height','text-align',
            'width','display','white-space','overflow','opacity',
            'background','background-color','padding','margin'
          ];
          props.forEach(p => {
            try { span.style.setProperty(p, computed.getPropertyValue(p)); } catch(e) {}
          });
          span.style.display = 'inline-block';
          inp.parentNode.replaceChild(span, inp);
        });
      }
    });

    const imgData = canvas.toDataURL('image/jpeg', 0.97);
    const pdf = new jsPDF({
      orientation: 'portrait',
      unit: 'mm',
      format: [w, h]
    });
    pdf.addImage(imgData, 'JPEG', 0, 0, w, h);
    pdf.save(`photostrip-${currentFormat}-${Date.now()}.pdf`);
  } finally {
    page.style.width     = prevStyles.width;
    page.style.height    = prevStyles.height;
    page.style.overflow  = prevStyles.overflow;
    page.style.position  = prevStyles.position;
    page.style.transform = prevStyles.transform;
    page.style.zoom      = prevStyles.zoom;
    btn.textContent = '⬇ Save as PDF';
    btn.disabled = false;
  }
}

/* ══════════════════════════════════════
   PRINT
══════════════════════════════════════ */
function printPage() {
  let styleEl = document.getElementById('print-page-style');
  if (!styleEl) {
    styleEl = document.createElement('style');
    styleEl.id = 'print-page-style';
    document.head.appendChild(styleEl);
  }
  const sizes = {
    a: '128mm 182mm',
    b: '128mm 182mm',
    c: '128mm 182mm'
  };
  styleEl.textContent = `@media print { @page { size: ${sizes[currentFormat]}; margin: 0; } }`;
  window.print();
}

/* ══════════════════════════════════════
   INIT
══════════════════════════════════════ */
render();